def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Score accounting
    my_score = 0
    opp_score = 0
    opp_c = 0
    my_c = 0
    for a, b in history:
        if a == 'C':
            my_c += 1
        if b == 'C':
            opp_c += 1
        if a == 'C' and b == 'C':
            my_score += 3
            opp_score += 3
        elif a == 'C' and b == 'D':
            opp_score += 5
        elif a == 'D' and b == 'C':
            my_score += 5
        else:
            my_score += 1
            opp_score += 1

    last_opp = history[-1][1]
    last_me = history[-1][0]

    # Endgame: extract remaining value from known cooperators, otherwise lock in.
    if n >= 95:
        if opp_c >= n - 2 or (opp_c > my_c + 2 and opp_c > n * 0.6):
            return 'D'
        if opp_c < n * 0.25:
            return 'D'
        return 'C'

    # Short opening: cooperate, but punish immediate persistent defection fast.
    if n < 6:
        if n >= 2 and history[-1][1] == 'D' and history[-2][1] == 'D':
            return 'D'
        return 'C'

    # Hard defectors: never reward them after enough evidence.
    if opp_c == 0:
        return 'D'
    if opp_c <= 2 and n >= 18:
        return 'D'

    # Recent behavior
    recent = history[-10:]
    opp_recent_c = 0
    for a, b in recent:
        if b == 'C':
            opp_recent_c += 1

    # Very cooperative opponent: cooperate but sneak occasional exploitation.
    if opp_recent_c >= 9:
        if n >= 25 and n < 92 and rng.random() < 0.07:
            return 'D'
        return 'C'

    # Sustained defection streak: punish, but occasionally probe for recovery.
    if opp_recent_c == 0:
        if rng.random() < 0.06:
            return 'C'
        return 'D'

    # Almost-always-defector recent block.
    if opp_recent_c <= 1:
        if rng.random() < 0.1:
            return 'C'
        return 'D'

    # Recover from mutual defection spirals: if both have been defecting,
    # try cooperation to reset, unless opponent seems to prefer defection.
    recent_my_c = 0
    for a, b in recent:
        if a == 'C':
            recent_my_c += 1
    if last_opp == 'D' and last_me == 'D' and recent_my_c <= 2:
        if opp_c * 2 >= n:
            if rng.random() < 0.35:
                return 'C'
            return 'D'

    # Forgiveness after isolated defections against otherwise cooperative players.
    if last_opp == 'D':
        opp_rate = opp_c / n
        if opp_rate > 0.7:
            if rng.random() < 0.75:
                return 'C'
            return 'D'
        if opp_rate > 0.4:
            if rng.random() < 0.3:
                return 'C'
            return 'D'
        return 'D'

    # Opponent cooperated last round.
    # If we are being exploited (our cooperation yield lags), defect occasionally.
    opp_rate = opp_c / n
    my_rate = my_c / n

    # Exploit overly cooperative opponents slightly more once trust established.
    if opp_rate > 0.85 and n > 15:
        if rng.random() < 0.12:
            return 'D'
        return 'C'

    # If we've cooperated much more than opponent, push back.
    if my_rate > opp_rate + 0.2 and n > 15:
        if rng.random() < 0.3:
            return 'D'
        return 'C'

    # Score-differential pressure: if losing badly, defect more to catch up,
    # but only against opponents with meaningful defection history.
    if opp_score > my_score + 10 and opp_rate < 0.85:
        if rng.random() < 0.35:
            return 'D'
        return 'C'

    # Punish a long streak of opponent defections even if last was C (testing).
    if n >= 4 and history[-2][1] == 'D' and history[-3][1] == 'D' and opp_rate < 0.7:
        if rng.random() < 0.5:
            return 'D'
        return 'C'

    # Mild random probing to discover exploitable opponents.
    if n > 30 and n < 90 and rng.random() < 0.04:
        return 'D'

    return 'C'
